INSERT INTO alert_template_locales(template_id,locale,title,body) VALUES
  ('1dcd447e-cd63-5de2-9261-5204f0c3d412','vi','Báo cháy khẩn cấp','Phát hiện cháy tại {{zone}}, tầng {{floor}}, tòa {{building}}. Di chuyển ngay theo lối thoát hiểm gần nhất, không dùng thang máy. Làm theo hướng dẫn của đội PCCC cơ sở.'),
  ('1dcd447e-cd63-5de2-9261-5204f0c3d412','en','Fire emergency','Fire detected in {{zone}}, floor {{floor}}, building {{building}}. Evacuate immediately via the nearest exit; do not use elevators. Follow the instructions of the fire wardens.'),
  ('ede88802-0aae-51e1-a5ff-f7ef36433d58','vi','Diễn tập PCCC','Đây là diễn tập PCCC tại {{zone}}, tầng {{floor}}, tòa {{building}}. Thực hiện quy trình sơ tán theo kế hoạch diễn tập, không hoảng loạn. Xác nhận đã nhận thông báo trên thiết bị.'),
  ('ede88802-0aae-51e1-a5ff-f7ef36433d58','en','Fire drill','This is a fire drill in {{zone}}, floor {{floor}}, building {{building}}. Follow the planned evacuation procedure calmly. Acknowledge receipt of this notification on your device.');
INSERT INTO demo_scenarios(id,scenario_key,label,enabled,definition_json) VALUES
  ('c90dc96b-c67e-5a44-affb-dec85ca197fc','FIRE_DRILL','Fire drill - Building B01',1,'{"scenarioKey":"FIRE_DRILL","simulation":true,"buildingCode":"B01","templateCode":"DRILL","locales":["vi","en"],"steps":[{"step":1,"action":"OPEN_INCIDENT","kind":"DRILL","openedBy":"operator"},{"step":2,"action":"PUBLISH_ALERT","templateCode":"DRILL","scope":{"buildingCode":"B01"},"requestedBy":"operator"},{"step":3,"action":"AWAIT_DEVICE_ACKS","expectedDevices":120,"timeoutSeconds":300},{"step":4,"action":"RESOLVE_INCIDENT","closedBy":"operator"}],"notes":"Training only - not a real emergency broadcast system."}');
